"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["96769"],{20059(e){e.exports=JSON.parse('{"id":"F271","slug":"pe-earnings-yield","name":"P/E Ratio and Earnings Yield","subject":"Equity Markets","section":"Equities","topic":"Fundamental analysis","level":"Beginner","aliases":["price earnings ratio","earnings multiple","fundamental analysis","earnings yield"],"formula":{"latex":"P/E=\\\\frac{P}{EPS},\\\\quad \\\\text{Earnings yield}=\\\\frac{EPS}{P}","also":[],"text":"P/E = Share price / Earnings per share; Earnings yield = Earnings per share / Share price"},"symbols":[{"symbol":"P","meaning":"Share price","unit":"money"},{"symbol":"EPS","meaning":"Earnings per share over the last 12 months (trailing) or the next 12 months (forward)","unit":"money"}],"when_to_use":"Use it as a quick check of how much investors pay for each unit of profit. The earnings yield is the same thing upside down and can be compared directly with a bond yield.","worked_example":{"problem":"A share costs 60 and earned 4 per share over the last year. It is expected to earn 4.80 next year. What are the trailing and forward P/E ratios and the earnings yield?","inputs":{"p":60,"eps":4,"f":4.8},"steps":[{"label":"Trailing P/E = price / EPS","working":"60 / 4","value":"15.00"},{"label":"Forward P/E = price / forward EPS","working":"60 / 4.8","value":"12.50"},{"label":"Earnings yield = EPS / price","working":"4 / 60","value":"6.67%"}],"answer":"The trailing P/E is 15.00 and the forward P/E is 12.50. The earnings yield is 6.67%, which you can compare with the yield on a bond."},"calculator":{"available":true,"inputs":[{"id":"p","label":"Share price","unit":"money","type":"number","default":60,"hint":""},{"id":"eps","label":"Trailing EPS","unit":"money","type":"number","default":4,"hint":""},{"id":"f","label":"Forward EPS","unit":"money","type":"number","default":4.8,"hint":""}],"checks":[{"expr":"p>0 and eps>0 and f>0","message":"Enter a price and earnings above zero."}],"steps":[{"id":"pe","label":"Trailing P/E = price / EPS","expr":"p/eps","format":"num2"},{"id":"fpe","label":"Forward P/E = price / forward EPS","expr":"p/f","format":"num2"},{"id":"ey","label":"Earnings yield = EPS / price","expr":"eps/p","format":"pct2"}],"results":["pe","fpe","ey"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"pe":15,"fpe":12.5,"ey":0.06666666666666667}},"finder":{"finds":"How much you pay for each unit of earnings","needs":"Price, earnings per share"},"related":[{"slug":"eps","name":"Earnings per Share (EPS)"},{"slug":"valuation-multiples","name":"Valuation Multiples (EV/EBITDA, EV/Sales, P/E)"},{"slug":"peg-ratio","name":"PEG Ratio"}],"related_ids":["F064","F219","F276"],"group":"Markets and instruments","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>P</mi><mi mathvariant=\\"normal\\">/</mi><mi>E</mi><mo>=</mo><mfrac><mi>P</mi><mrow><mi>E</mi><mi>P</mi><mi>S</mi></mrow></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Earnings\xa0yield</mtext><mo>=</mo><mfrac><mrow><mi>E</mi><mi>P</mi><mi>S</mi></mrow><mi>P</mi></mfrac></mrow><annotation encoding=\\"application/x-tex\\">P/E=\\\\frac{P}{EPS},\\\\quad \\\\text{Earnings yield}=\\\\frac{EPS}{P}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"dilution-from-new-issue","name":"Ownership Dilution from a New Share Issue"},"next":{"slug":"pairs-trade-sizing","name":"Pairs Trade Sizing and Reversion Profit"},"lesson":null,"total":522}')}}]);